// This file is generated by AI.

// 中间格式的数据模型与文本互转: 解析、序列化、格式化、导出 WebGAL 脚本。
//
// 中间格式行文法 (每行一条):
//   `:正文`          旁白
//   `%:正文`         对话 (说话者未分配, `%` 为占位符)
//   `人物名:正文`     对话 (已分配)
//   `正文`           跟随 (无前缀, 继承紧邻上一条有前缀行的声道)
//
// 由于预处理阶段已将正文内的半角 `:` `;` 转成全角, 因此正文不含半角冒号,
// 行首前缀可无歧义地解析。

export type LineKind = 'narration' | 'dialogue' | 'comment';

export interface Line {
  kind: LineKind;
  /** 旁白恒为 null; 对话段首行为名字或 null(未分配); 跟随行恒为 null(继承段首); 注释恒为 null。 */
  speaker: string | null;
  /** 正文 (已去引号、已断句); 注释行为 `;` 后的内容。 */
  text: string;
  /** 是否为「无前缀」跟随行 (注释恒为 false)。 */
  follow: boolean;
}

export interface Segment {
  /** 段首行下标。 */
  head: number;
  /** 段首 + 跟随行下标 (连续)。 */
  lines: number[];
  /** 说话者 (null = 未分配)。 */
  speaker: string | null;
}

export interface DocumentModel {
  lines: Line[];
  segments: Segment[];
}

export interface Speaker {
  /** 键位: 1-9 后接 A-Z。 */
  key: string;
  name: string;
  figureId?: string;
}

export type Severity = 'error' | 'warning' | 'info';

export interface Diagnostic {
  /** 0 基行号。 */
  line: number;
  severity: Severity;
  message: string;
}

export interface ParseResult {
  model: DocumentModel;
  diagnostics: Diagnostic[];
}

export interface ExportOptions {
  speakers: Speaker[];
}

// -------- 解析 --------

function checkBody(text: string, line: number, diags: Diagnostic[]): string {
  const t = text.trim();
  if (t.includes(':') || t.includes(';')) {
    diags.push({
      line,
      severity: 'warning',
      message: '正文中包含半角冒号/分号, 可能被误解析为前缀或语句结束符',
    });
  }
  return t;
}

/** 解析中间格式文本为模型, 同时产出诊断。 */
export function parse(text: string): ParseResult {
  const diagnostics: Diagnostic[] = [];
  const lines: Line[] = [];
  const raw = text.split(/\r?\n/);

  for (let i = 0; i < raw.length; i++) {
    const src = raw[i].trim();
    if (src === '') continue;
    // `;` 注释行 (原句 / 警告): 保留在模型中, 行号与可见文本一致。
    if (src.startsWith(';')) {
      lines.push({ kind: 'comment', speaker: null, text: src.slice(1).trim(), follow: false });
      continue;
    }
    if (src.startsWith('%:')) {
      lines.push({ kind: 'dialogue', speaker: null, text: checkBody(src.slice(2), i, diagnostics), follow: false });
    } else if (src.startsWith(':')) {
      lines.push({ kind: 'narration', speaker: null, text: checkBody(src.slice(1), i, diagnostics), follow: false });
    } else {
      const m = /^([^:%\s][^:]*?):/.exec(src);
      if (m) {
        lines.push({
          kind: 'dialogue',
          speaker: m[1].trim(),
          text: checkBody(src.slice(m[0].length), i, diagnostics),
          follow: false,
        });
      } else {
        // 无前缀跟随行: 其声道由紧邻上一条有前缀行决定 (见 buildSegments)。
        lines.push({ kind: 'narration', speaker: null, text: checkBody(src, i, diagnostics), follow: true });
      }
    }
  }

  return { model: buildSegments(lines, diagnostics), diagnostics };
}

function buildSegments(lines: Line[], diags: Diagnostic[]): DocumentModel {
  const segments: Segment[] = [];
  let current: Segment | null = null;
  let lastAnchor: LineKind | null = null;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    // 注释行不影响跟随解析与分段。
    if (line.kind === 'comment') continue;
    if (line.follow) {
      if (lastAnchor === 'dialogue') {
        line.kind = 'dialogue';
        if (current) current.lines.push(i);
        else diags.push({ line: i, severity: 'warning', message: '无前缀行缺少可跟随的对话' });
      } else {
        line.kind = 'narration';
        diags.push({ line: i, severity: 'warning', message: '无前缀行跟随了旁白, 已按旁白处理' });
      }
      continue;
    }
    lastAnchor = line.kind;
    if (line.kind === 'dialogue') {
      current = { head: i, lines: [i], speaker: line.speaker };
      segments.push(current);
    } else {
      current = null;
    }
  }

  for (const s of segments) s.speaker = lines[s.head].speaker;
  return { lines, segments };
}

// -------- 序列化 / 格式化 --------

function collapseSpaces(s: string): string {
  return s.trim().replace(/[\s\u3000]+/g, ' ');
}

/** 将模型序列化回中间格式文本。 */
export function serialize(model: DocumentModel): string {
  return model.lines
    .map((line) => {
      if (line.kind === 'comment') return `; ${line.text}`;
      if (line.follow) return line.text;
      if (line.kind === 'narration') return `:${line.text}`;
      return line.speaker === null ? `%:${line.text}` : `${line.speaker}:${line.text}`;
    })
    .join('\n');
}

/** 格式化中间格式文本 (规整行内空格, 保留前缀与结构)。 */
export function formatIntermediate(text: string): string {
  return text
    .split(/\r?\n/)
    .map((line) => {
      const t = line.trim();
      if (t.startsWith('%:')) return `%:${collapseSpaces(t.slice(2))}`;
      if (t.startsWith(':')) return `:${collapseSpaces(t.slice(1))}`;
      const m = /^([^:%\s][^:]*?):/.exec(t);
      if (m) return `${m[0]}${collapseSpaces(t.slice(m[0].length))}`;
      return collapseSpaces(t);
    })
    .join('\n');
}

// -------- 导出 WebGAL 脚本 --------

/** 从「编号-名称」说话者串中提取人物名称 (无编号前缀时原样返回)。 */
function speakerName(speaker: string): string {
  const m = /^[1-9A-Z]-(.+)$/.exec(speaker);
  return m ? m[1] : speaker;
}

/** 将模型导出为原始 WebGAL 脚本 (旁白 `:正文;`, 对话 `人物名:正文;`)。 */
export function toWebGALScript(model: DocumentModel, opts: ExportOptions): string {
  const byName = new Map(opts.speakers.map((s) => [s.name, s]));
  const speakerOf = new Array<string | null>(model.lines.length).fill(null);
  for (const seg of model.segments) {
    for (const idx of seg.lines) speakerOf[idx] = seg.speaker;
  }

  const out: string[] = [];
  for (let i = 0; i < model.lines.length; i++) {
    const line = model.lines[i];
    // 注释行在生成脚本时忽略。
    if (line.kind === 'comment') continue;
    if (line.kind === 'narration') {
      out.push(`:${line.text};`);
      continue;
    }
    const speaker = speakerOf[i];
    if (speaker === null) {
      // 未分配: 视为旁白。
      out.push(`:${line.text};`);
      continue;
    }
    const name = speakerName(speaker);
    const figure = byName.get(name)?.figureId;
    out.push(`${name}:${line.text}${figure ? ` -figureId=${figure}` : ''};`);
  }
  return out.join('\n');
}
